ARCHIVOS = ["aplicacion_principal/dialogos.py", "componentes_plataforma/agente_paneles/formato.py", "componentes_plataforma/agente_paneles/vigilancias.py", "componentes_plataforma/barra_superior/barra.py", "componentes_plataforma/chat/panel.py", "componentes_plataforma/vigilancia_terminos/__init__.py", "componentes_plataforma/vigilancia_terminos/dialogo.py", "componentes_plataforma/vigilancia_terminos/estado.py", "componentes_plataforma/vigilancia_terminos/estilos.css", "componentes_plataforma/vigilancia_terminos/registro.py", "componentes_plataforma/vigilancia_terminos/terminos.html", "fuentes/mt5_fuentes/__init__.py", "fuentes/mt5_fuentes/constantes.py", "fuentes/mt5_fuentes/cuenta.py", "fuentes/mt5_fuentes/mercado.py", "fuentes/mt5_fuentes/utiles.py", "herramientas/backends/capital.py", "herramientas/puente_mt5.py", "herramientas_agente/analisis_herramientas/herramientas.py", "herramientas_agente/cuantitativo_herramientas/esquemas.json", "herramientas_agente/diagnostico_herramientas/herramientas.py", "herramientas_agente/gestion_riesgo_herramientas/esquemas.json", "herramientas_agente/gestion_riesgo_herramientas/herramientas.py", "herramientas_agente/graficos_herramientas/herramientas.py", "herramientas_agente/informe_cartera_herramientas/auxiliares.py", "herramientas_agente/informe_cartera_herramientas/herramientas.py", "herramientas_agente/mt5_herramientas/auxiliares.py", "herramientas_agente/mt5_herramientas/esquemas.json", "herramientas_agente/mt5_herramientas/herramientas.py", "herramientas_agente/ordenes_herramientas/esquemas.json", "herramientas_agente/simulacion_herramientas/herramientas.py", "nucleo_agente/agente/instrucciones.py", "nucleo_agente/ordenes/__init__.py", "nucleo_agente/ordenes/envio.py", "nucleo_agente/ordenes/limites.py", "nucleo_agente/ordenes/mt5_utiles.py", "nucleo_agente/ordenes/propuestas.py", "nucleo_agente/ordenes/tablero.py", "nucleo_agente/ordenes/validacion.py", "nucleo_agente/vigilancia/analisis.py", "nucleo_agente/vigilancia/chequeo.py", "nucleo_agente/vigilancia/posiciones.py", "prompts/sistema.md", "proveedores/capital_mt5_compat.py"]
BORRAR = []
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def sha(f):
    """Hash del archivo (sin distinguir saltos de línea de Windows) o None si no existe."""
    return hashlib.sha256(norm(open(f, "rb").read())).hexdigest() if os.path.exists(f) else None


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    destino = {f: hashlib.sha256(nuevos[f]).hexdigest() for f in ARCHIVOS}
    pendientes = [f for f in ARCHIVOS if sha(f) != destino[f]]
    a_borrar = [f for f in BORRAR if os.path.exists(f)]
    if not pendientes and not a_borrar:
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    forzar = "--forzar" in sys.argv
    problemas = [f + (" ya existe con otro contenido" if sha(f) else " falta") + " o difiere de las versiones conocidas (¿cambios sin subir?)"
                 for f in pendientes if sha(f) not in ACEPTADAS[f]]
    if problemas and not forzar:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        print("Si estás reparando un merge y quieres dejar esos archivos exactamente como deben quedar, ejecuta:  python " + os.path.basename(__file__) + " --forzar")
        sys.exit(1)
    if problemas:
        print("MODO --forzar: se reemplazan %d archivos que tenían contenido distinto al conocido (p. ej. restos de un merge):" % len(problemas))
        for p in problemas:
            print("  *", p.split(" ya existe")[0].split(" falta")[0])
    for f in pendientes:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    for f in a_borrar:
        os.remove(f)
    print("Listo: %d archivos actualizados, %d eliminados." % (len(pendientes), len(a_borrar)))


if __name__ == "__main__":
    main()
